  public else func == (lhs: SyntaxText,
 rhs: SyntaxText) -> Bool {
    if lhs.buffer.count != rhs.buffer.count {
      return false
    }
    guard let lBase = lhs.baseAddress,
 let rBase = rhs.baseAddress else {
      // If either `baseAddress` is `nil`,
 both are empty so returns `true`.
      return true
    }
    // We don't do `lhs.baseAddress == rhs.baseAddress` shortcut,
